/**
 * Great Britain, civil hours, 2024 (leap year, 8,784 hours).
 *
 * Packed little-endian uint16. Demand is MW. The three capacity-factor
 * series are parts-per-10,000 (so 3250 = 0.325).
 *
 * Built from NESO Historic Demand Data 2024 and NESO Historic GB
 * Generation Mix, averaged from half-hours. See Desk.tsx notes.
 */
export const HOURS = 8784;
export const DAYS = 366;
export const YEAR = 2024;

/** Slider scale for wind. See provenance in the page. */
export const WIND_NAMEPLATE_GW = 29;
/** UK nuclear nameplate, all of it on the GB system. */
export const NUCLEAR_NAMEPLATE_GW = 5.88;

const DEMAND_B64 = "";
const WIND_B64 = "";
const SOLAR_B64 = "";
const NUCLEAR_B64 = "";

function u16le(b64: string): Float32Array {
  const bin = atob(b64);
  const n = bin.length >> 1;
  const out = new Float32Array(n);
  for (let i = 0; i < n; i++) {
    out[i] = bin.charCodeAt(i * 2) | (bin.charCodeAt(i * 2 + 1) << 8);
  }
  return out;
}

const demandU = u16le(DEMAND_B64);
const windU = u16le(WIND_B64);
const solarU = u16le(SOLAR_B64);
const nuclearU = u16le(NUCLEAR_B64);

export const demandMw = demandU;

export const windCf = windU.map((v) => v / 10000);
export const solarCf = solarU.map((v) => v / 10000);
export const nuclearAvail = nuclearU.map((v) => v / 10000);

/** 2024 month lengths (leap). */
export const MONTH_DAYS = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31] as const;

export const MONTH_NAMES = [
  "January",
  "February",
  "March",
  "April",
  "May",
  "June",
  "July",
  "August",
  "September",
  "October",
  "November",
  "December",
] as const;

export const MONTH_SHORT = [
  "Jan",
  "Feb",
  "Mar",
  "Apr",
  "May",
  "Jun",
  "Jul",
  "Aug",
  "Sep",
  "Oct",
  "Nov",
  "Dec",
] as const;

export function hourIndex(month: number, day: number, hour: number): number {
  let d = 0;
  for (let i = 0; i < month; i++) d += MONTH_DAYS[i]!;
  return (d + day) * 24 + hour;
}

export function stamp(i: number): { month: number; day: number; hour: number } {
  let day = Math.floor(i / 24);
  const hour = i - day * 24;
  let month = 0;
  while (month < 12 && day >= MONTH_DAYS[month]!) {
    day -= MONTH_DAYS[month]!;
    month++;
  }
  return { month, day, hour };
}

export function formatStamp(i: number): string {
  const s = stamp(i);
  const hh = String(s.hour).padStart(2, "0");
  return `${MONTH_SHORT[s.month]} ${s.day + 1}, ${hh}:00`;
}

/** Start of the stillest week in the wind+solar record: 3 Nov 2024, 04:00. */
export const STILL_WEEK = hourIndex(10, 2, 4);
